import React from "react";

const ChatWindow = ({ messages }) => {
  return (
    <div style={{ height: "400px", overflowY: "auto", border: "1px solid #ccc", padding: "10px" }}>
      {messages.map((msg, index) => (
        <div key={index}>
          <b>{msg.sender}:</b> {msg.text}
        </div>
      ))}
    </div>
  );
};

export default ChatWindow;
